function integerSqrt(n) {
  let low = 0
  let high = Math.min(n, 1_000_000)
  while (low < high) {
    const mid = Math.floor((low + high + 1) / 2)
    if (mid * mid <= n) low = mid
    else high = mid - 1
  }
  return low
}

